var DATA = {"stage": "Create", "entry": "Valid minimum fields present", "exit": "ID assigned and provenance stamped", "retention": "Permanent (birth facts)", "next": "Validate"};
var STAGES = ["create", "validate", "enrich", "publish", "archive", "expire", "purge"];
console.log("Lifecycle stage: " + DATA.stage);
console.log("Entry: " + DATA.entry + " | Exit: " + DATA.exit + " | Retention: " + DATA.retention);
var idx = STAGES.indexOf(DATA.stage.toLowerCase().split(" ")[0]);
var rec = { id: "rec-1", stage: DATA.stage, history: [] };
for (var i = 0; i <= idx && i < STAGES.length; i++) {
  rec.history.push(STAGES[i]);
  console.log("  -> " + STAGES[i]);
}
console.log("Next stage: " + DATA.next);
console.log("RESULT: record walked the lifecycle to '" + DATA.stage + "' (" + rec.history.length + " stages).");

